//! Style gauntlet — loads fixtures/style_gauntlet.xlsx (generated by
//! scripts/make_style_gauntlet.py), where every case row carries a JSON
//! spec describing the styling its target cell must have, and asserts
//! the loaded IronCalc model matches. Runs twice:
//!
//!   1. xlsx load fidelity (IronCalc reader + fastsheet load pipeline)
//!   2. save-to-.xls + reload round-trip (exercises the BIFF style
//!      writer: FONT / XF / PALETTE / FORMAT / COLINFO / ROW / PANE)
//!
//! Known losses are recorded per phase in the KNOWN_* baselines as
//! failure-string prefixes; a new failure OR a newly-passing baseline
//! entry both fail the test loudly (same contract as the formula
//! gauntlet).

use std::collections::{HashMap, HashSet};

use ironcalc::base::Model;
use serde_json::Value;

const FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../fixtures/style_gauntlet.xlsx"
);

/// Failure prefixes accepted after the plain xlsx load.
const KNOWN_XLSX: &[&str] = &[
    // IronCalc's formatter has no fraction renderer — "# ?/?" formats
    // parse but render garbage. The format STRING itself survives.
    "NumFmts!r9 shows",
    "NumFmts!r10 shows",
];

/// Failure prefixes accepted after the xls save+reload round-trip.
const KNOWN_XLS: &[&str] = &[
    // Same fraction-renderer limitation as the xlsx phase.
    "NumFmts!r9 shows",
    "NumFmts!r10 shows",
    // The xls load numfmt gate (numfmt_renders_cleanly) rejects
    // formats IronCalc can't parse, so [$-409]… is deliberately not
    // applied on reload; the cell falls back to the date default.
    "NumFmts!r30 numfmt",
    // BIFF valign bottom (2) IS the default — the loader treats it as
    // "no explicit alignment", which renders identically.
    "Alignment!r11 valign",
    // IronCalc's Col struct has no hidden field, so column hiddenness
    // lives in an AppState side-channel that save_xls(model) never
    // sees. xls→xls saves keep it via COLINFO passthrough; an
    // xlsx-sourced model can't carry it into a .xls save.
    "Geometry!r9 colhidden",
];

enum HiddenCols<'a> {
    /// xlsx phase: raw zip bytes, scraped per sheet path.
    Xlsx(&'a [u8]),
    /// xls phase: the loader's side-channel map.
    Xls(&'a HashMap<u32, HashSet<i32>>),
}

fn spec_rows(model: &Model) -> Vec<(u32, String, i32, Value)> {
    let mut out = vec![];
    for (s, ws) in model.workbook.worksheets.iter().enumerate() {
        for row in 1..=200 {
            for col in [4, 10] {
                let text = model
                    .get_formatted_cell_value(s as u32, row, col)
                    .unwrap_or_default();
                if text.starts_with('{') {
                    if let Ok(v) = serde_json::from_str::<Value>(&text) {
                        out.push((s as u32, ws.name.clone(), row, v));
                    }
                }
            }
        }
    }
    out
}

fn norm_color(c: &str) -> String {
    c.to_uppercase()
}

#[allow(clippy::too_many_lines)]
fn check(
    model: &Model,
    hidden: &HiddenCols,
    sheet: u32,
    sheet_name: &str,
    row: i32,
    spec: &Value,
) -> Vec<String> {
    let mut fails = vec![];
    let id = |key: &str| format!("{sheet_name}!r{row} {key}");
    let mut fail = |key: &str, msg: String| fails.push(format!("{}: {msg}", id(key)));
    let style = model
        .get_style_for_cell(sheet, row, 3)
        .unwrap_or_default();
    let ws = &model.workbook.worksheets[sheet as usize];

    if let Some(font) = spec.get("font").and_then(|v| v.as_object()) {
        if let Some(name) = font.get("name").and_then(|v| v.as_str()) {
            if style.font.name != name {
                fail("font.name", format!("expected {name:?} got {:?}", style.font.name));
            }
        }
        if let Some(sz) = font.get("sz").and_then(|v| v.as_i64()) {
            if style.font.sz != sz as i32 {
                fail("font.sz", format!("expected {sz} got {}", style.font.sz));
            }
        }
        for (key, actual) in [
            ("b", style.font.b),
            ("i", style.font.i),
            ("u", style.font.u),
            ("strike", style.font.strike),
        ] {
            if let Some(expected) = font.get(key).and_then(|v| v.as_bool()) {
                if actual != expected {
                    fail(&format!("font.{key}"), format!("expected {expected} got {actual}"));
                }
            }
        }
        if let Some(color) = font.get("color").and_then(|v| v.as_str()) {
            let actual = style.font.color.as_deref().map(norm_color);
            if actual.as_deref() != Some(&norm_color(color)[..]) {
                fail("font.color", format!("expected {color:?} got {actual:?}"));
            }
        }
    }

    if let Some(fill) = spec.get("fill").and_then(|v| v.as_str()) {
        if style.fill.pattern_type != "solid" {
            fail("fill.pattern", format!("expected solid got {:?}", style.fill.pattern_type));
        }
        let actual = style.fill.fg_color.as_deref().map(norm_color);
        if actual.as_deref() != Some(&norm_color(fill)[..]) {
            fail("fill.fg", format!("expected {fill:?} got {actual:?}"));
        }
    }

    if let Some(fmt) = spec.get("numfmt").and_then(|v| v.as_str()) {
        if style.num_fmt != fmt {
            fail("numfmt", format!("expected {fmt:?} got {:?}", style.num_fmt));
        }
    }
    if let Some(shows) = spec.get("shows").and_then(|v| v.as_str()) {
        let actual = model
            .get_formatted_cell_value(sheet, row, 3)
            .unwrap_or_default();
        if actual != shows {
            fail("shows", format!("expected {shows:?} got {actual:?}"));
        }
    }

    if let Some(h) = spec.get("halign").and_then(|v| v.as_str()) {
        let actual = style
            .alignment
            .as_ref()
            .map(|a| format!("{:?}", a.horizontal).to_lowercase());
        if actual.as_deref() != Some(h) {
            fail("halign", format!("expected {h:?} got {actual:?}"));
        }
    }
    if let Some(v) = spec.get("valign").and_then(|x| x.as_str()) {
        let actual = style
            .alignment
            .as_ref()
            .map(|a| format!("{:?}", a.vertical).to_lowercase());
        if actual.as_deref() != Some(v) {
            fail("valign", format!("expected {v:?} got {actual:?}"));
        }
    }
    if let Some(w) = spec.get("wrap").and_then(|v| v.as_bool()) {
        let actual = style.alignment.as_ref().map(|a| a.wrap_text).unwrap_or(false);
        if actual != w {
            fail("wrap", format!("expected {w} got {actual}"));
        }
    }

    if let Some(border) = spec.get("border").and_then(|v| v.as_object()) {
        for (edge, expected) in border {
            let item = match edge.as_str() {
                "left" => &style.border.left,
                "right" => &style.border.right,
                "top" => &style.border.top,
                "bottom" => &style.border.bottom,
                _ => continue,
            };
            let key = format!("border.{edge}.style");
            match item {
                None => fail(&key, "expected Some(border) got None".to_string()),
                Some(item) => {
                    if let Some(bs) = expected.get("style").and_then(|v| v.as_str()) {
                        let actual = item.style.to_string().to_lowercase();
                        if actual != bs {
                            fail(&key, format!("expected {bs:?} got {actual:?}"));
                        }
                    }
                    if let Some(bc) = expected.get("color").and_then(|v| v.as_str()) {
                        let actual = item.color.as_deref().map(norm_color);
                        if actual.as_deref() != Some(&norm_color(bc)[..]) {
                            fail(
                                &format!("border.{edge}.color"),
                                format!("expected {bc:?} got {actual:?}"),
                            );
                        }
                    }
                }
            }
        }
    }

    if let Some(rng) = spec.get("merge").and_then(|v| v.as_str()) {
        let found = ws
            .merge_cells
            .iter()
            .any(|m| m.replace('$', "").eq_ignore_ascii_case(rng));
        if !found {
            fail("merge", format!("range {rng:?} not in merge list {:?}", ws.merge_cells));
        }
    }

    if let Some(cw) = spec.get("colwidth") {
        let col = cw["col"].as_i64().unwrap_or(0) as i32;
        let chars = cw["chars"].as_f64().unwrap_or(0.0);
        let expected = chars * 12.0;
        let actual = model.get_column_width(sheet, col).unwrap_or(-1.0);
        if (actual - expected).abs() > 6.0 {
            fail("colwidth", format!("col {col}: expected ~{expected} got {actual}"));
        }
    }
    if let Some(pt) = spec.get("rowheight_pt").and_then(|v| v.as_f64()) {
        let expected = pt * 2.0;
        let actual = model.get_row_height(sheet, row).unwrap_or(-1.0);
        if (actual - expected).abs() > 1.0 {
            fail("rowheight", format!("expected ~{expected} got {actual}"));
        }
    }
    if spec.get("rowhidden").and_then(|v| v.as_bool()) == Some(true) {
        let actual = ws.rows.iter().find(|r| r.r == row).map(|r| r.hidden);
        if actual != Some(true) {
            fail("rowhidden", format!("expected hidden row, got {actual:?}"));
        }
    }
    if let Some(col) = spec.get("colhidden").and_then(|v| v.as_i64()) {
        let col = col as i32;
        let is_hidden = match hidden {
            HiddenCols::Xlsx(bytes) => {
                let path = format!("xl/worksheets/sheet{}.xml", sheet + 1);
                fastsheet_lib::extract_hidden_col_ranges(bytes, &path)
                    .iter()
                    .any(|(a, b)| col >= *a && col <= *b)
            }
            HiddenCols::Xls(map) => map
                .get(&sheet)
                .map(|set| set.contains(&col))
                .unwrap_or(false),
        };
        if !is_hidden {
            fail("colhidden", format!("expected column {col} hidden"));
        }
    }
    if let Some(fr) = spec.get("frozen") {
        let rows = fr["rows"].as_i64().unwrap_or(0) as i32;
        let cols = fr["cols"].as_i64().unwrap_or(0) as i32;
        if ws.frozen_rows != rows || ws.frozen_columns != cols {
            fail(
                "frozen",
                format!(
                    "expected {rows}r/{cols}c got {}r/{}c",
                    ws.frozen_rows, ws.frozen_columns
                ),
            );
        }
    }
    if spec.get("survive").and_then(|v| v.as_bool()) == Some(true) {
        let actual = model
            .get_formatted_cell_value(sheet, row, 3)
            .unwrap_or_default();
        if !actual.starts_with("survives:") {
            fail("survive", format!("value lost, got {actual:?}"));
        }
    }
    fails
}

fn run_phase(model: &Model, hidden: &HiddenCols, phase: &str, baseline: &[&str]) {
    let specs = spec_rows(model);
    assert!(
        specs.len() > 80,
        "{phase}: only {} spec rows found — fixture wrong?",
        specs.len()
    );
    let mut failures = vec![];
    for (sheet, name, row, spec) in &specs {
        failures.extend(check(model, hidden, *sheet, name, *row, spec));
    }
    println!("style gauntlet [{phase}]: {} specs, {} failures", specs.len(), failures.len());
    for f in &failures {
        println!("  FAIL {f}");
    }
    let unexpected: Vec<_> = failures
        .iter()
        .filter(|f| !baseline.iter().any(|k| f.starts_with(k)))
        .collect();
    let fixed: Vec<_> = baseline
        .iter()
        .filter(|k| !failures.iter().any(|f| f.starts_with(**k)))
        .collect();
    assert!(
        unexpected.is_empty(),
        "[{phase}] unexpected style failures:\n{}",
        unexpected
            .iter()
            .map(|s| format!("  {s}"))
            .collect::<Vec<_>>()
            .join("\n")
    );
    assert!(
        fixed.is_empty(),
        "[{phase}] baseline entries now pass — prune: {fixed:?}"
    );
}

#[test]
fn style_gauntlet_xlsx_load() {
    let bytes = std::fs::read(FIXTURE).expect("read fixture");
    let mut model = fastsheet_lib::load_xlsx_with_fallback(FIXTURE).expect("load xlsx");
    model.evaluate();
    run_phase(&model, &HiddenCols::Xlsx(&bytes), "xlsx", KNOWN_XLSX);
}

#[test]
fn style_gauntlet_xls_round_trip() {
    let mut model = fastsheet_lib::load_xlsx_with_fallback(FIXTURE).expect("load xlsx");
    model.evaluate();
    let out = std::env::temp_dir().join("fastsheet_style_gauntlet.xls");
    fastsheet_lib::save_xls(&model, &out).expect("save xls");
    let (mut reloaded, hidden_cols, _, _) =
        fastsheet_lib::load_xls(&out.to_string_lossy()).expect("reload xls");
    reloaded.evaluate();
    run_phase(&reloaded, &HiddenCols::Xls(&hidden_cols), "xls-rt", KNOWN_XLS);
}
